#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

TARGET_NODE_VERSION="22.23.4"
TARGET_NODE_LABEL="v$TARGET_NODE_VERSION"
NVM_VERSION="v0.40.8"
PM2_VERSION="6.0.8"
PROJECT_ROOT="${PROJECT_ROOT:-/root/luykin-chaineye-service}"
NVM_DIR="${NVM_DIR:-/root/.nvm}"
BACKUP_ROOT="${BACKUP_ROOT:-/root/node-upgrade-backups}"
HEALTH_URL="${HEALTH_URL:-http://127.0.0.1:8087/api/internal-x9k2m7p4q8/health}"
SYSTEM_NODE="/usr/bin/node"
SYSTEM_PM2_JS="/usr/local/lib/node_modules/pm2/bin/pm2"
SYSTEM_PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
BACKUP_DIR=""
TARGET_BIN=""
TARGET_NODE=""
TARGET_PM2=""
CUTOVER_STARTED=0

umask 077

print_rollback_hint() {
  printf '\n'
  warn "If the new runtime has taken over, use the rollback section in the runbook."
  note "System runtime remains available at $SYSTEM_NODE."
  [[ -n "$BACKUP_DIR" ]] && note "This run's backup directory: $BACKUP_DIR"
}

on_error() {
  local exit_code=$? line_no="${1:-unknown}"
  trap - ERR
  printf '\n%s✗ Wizard stopped at line %s (exit %s).%s\n' "$RED" "$line_no" "$exit_code" "$RESET" >&2
  if (( CUTOVER_STARTED )); then
    print_rollback_hint >&2
  else
    warn "Cutover had not started; the running PM2 services were not intentionally stopped." >&2
  fi
  exit "$exit_code"
}
trap 'on_error $LINENO' ERR

source_nvm() {
  export NVM_DIR
  # shellcheck source=/dev/null
  . "$NVM_DIR/nvm.sh"
}

pm2_target() {
  env PATH="$TARGET_BIN:$SYSTEM_PATH" "$TARGET_PM2" "$@"
}

pm2_system() {
  env PATH="$SYSTEM_PATH" "$SYSTEM_NODE" "$SYSTEM_PM2_JS" "$@"
}

sanitized_pm2_summary() {
  local pm2_command="$1" parser_node="$2"
  "$parser_node" "$pm2_command" jlist 2>/dev/null | "$parser_node" -e '
    let input = "";
    process.stdin.on("data", (chunk) => { input += chunk; });
    process.stdin.on("end", () => {
      for (const item of JSON.parse(input)) {
        const env = item.pm2_env || {};
        console.log(JSON.stringify({
          id: item.pm_id,
          name: item.name,
          pid: item.pid,
          status: env.status,
          nodeVersion: env.node_version || null,
          restartCount: env.restart_time
        }));
      }
    });
  '
}

verify_expected_apps_online() {
  pm2_target jlist 2>/dev/null | "$TARGET_NODE" -e '
    let input = "";
    const expected = [
      "luykin-chaineye-api",
      "luykin-chaineye-crawler",
      "luykin-chaineye-bot",
      "luykin-chaineye-jobs"
    ];
    process.stdin.on("data", (chunk) => { input += chunk; });
    process.stdin.on("end", () => {
      const items = JSON.parse(input);
      const failures = [];
      for (const name of expected) {
        const matches = items.filter((item) => item.name === name);
        if (matches.length === 0) failures.push(name + ": missing");
        for (const item of matches) {
          if (item.pm2_env?.status !== "online") {
            failures.push(name + ": " + String(item.pm2_env?.status || "unknown"));
          }
        }
      }
      if (failures.length) {
        console.error(failures.join("\n"));
        process.exit(1);
      }
    });
  '
}

verify_worker_node_versions() {
  local failed=0
  while read -r app_name pid; do
    [[ -n "$pid" ]] || continue
    local executable version
    executable=$(readlink -f "/proc/$pid/exe" 2>/dev/null || true)
    version=$("/proc/$pid/exe" --version 2>/dev/null || true)
    printf '  %-32s pid=%-8s exe=%-24s version=%s\n' "$app_name" "$pid" "$executable" "$version"
    if [[ "$version" != "$TARGET_NODE_LABEL" ]]; then
      failed=1
    fi
  done < <(
    pm2_target jlist 2>/dev/null | "$TARGET_NODE" -e '
      let input = "";
      process.stdin.on("data", (chunk) => { input += chunk; });
      process.stdin.on("end", () => {
        for (const item of JSON.parse(input)) {
          if (String(item.name || "").startsWith("luykin-chaineye-")) {
            console.log(item.name + " " + item.pid);
          }
        }
      });
    '
  )
  return "$failed"
}

wait_for_health() {
  local attempt
  for attempt in $(seq 1 15); do
    if curl -fsS --max-time 5 "$HEALTH_URL" >/dev/null; then
      return 0
    fi
    sleep 2
  done
  return 1
}

rollback_to_system_node() {
  warn "Rolling PM2 back to the system Node runtime."
  if [[ -n "$TARGET_PM2" && -x "$TARGET_PM2" ]]; then
    pm2_target kill || true
  else
    pm2_system kill || true
  fi
  pm2_system resurrect
  pm2_system restart \
    luykin-chaineye-api \
    luykin-chaineye-crawler \
    luykin-chaineye-bot \
    luykin-chaineye-jobs \
    --update-env
  pm2_system save --force
  sleep 3
  sanitized_pm2_summary "$SYSTEM_PM2_JS" "$SYSTEM_NODE"
  if curl -fsS --max-time 10 "$HEALTH_URL" >/dev/null; then
    say "Rollback health check passed."
  else
    warn "Rollback completed, but the API health check still fails. Inspect PM2 logs."
  fi
}

banner "XHunt production Node.js security upgrade"

stage "Read-only preflight"
say "Target: Node.js $TARGET_NODE_VERSION with PM2 $PM2_VERSION."
say "Project: $PROJECT_ROOT"
warn "The login shell is fish; this wizard runs under Bash and never relies on fish loading nvm."
[[ "$EUID" -eq 0 ]] || { warn "Run this wizard as root on the production host."; exit 1; }
[[ -d "$PROJECT_ROOT/.git" ]] || { warn "Project repository not found at $PROJECT_ROOT."; exit 1; }
[[ -x "$SYSTEM_NODE" ]] || { warn "System Node not found at $SYSTEM_NODE."; exit 1; }
[[ -f "$SYSTEM_PM2_JS" ]] || { warn "System PM2 entrypoint not found at $SYSTEM_PM2_JS."; exit 1; }
for required_command in curl git npm readlink; do
  command -v "$required_command" >/dev/null 2>&1 || { warn "Missing command: $required_command"; exit 1; }
done
step "Current runtime"
"$SYSTEM_NODE" --version
pm2_system --version
step "Disk availability"
df -h /root "$PROJECT_ROOT" | sed -n '1,4p'
step "Current commit and working tree"
git -C "$PROJECT_ROOT" rev-parse HEAD
if [[ -n "$(git -C "$PROJECT_ROOT" status --short)" ]]; then
  warn "The production worktree is dirty. This runtime-only procedure will not modify Git files."
  git -C "$PROJECT_ROOT" status --short
fi
step "Current PM2 application summary"
sanitized_pm2_summary "$SYSTEM_PM2_JS" "$SYSTEM_NODE"
if curl -fsS --max-time 10 "$HEALTH_URL" >/dev/null; then
  say "Baseline API health check passed."
else
  warn "Baseline API health check failed: $HEALTH_URL"
  confirm "Continue despite a failed baseline health check?" || exit 1
fi
pause "Review the baseline, then press Enter to continue."

stage "Create the rollback point"
say "This refreshes PM2's dump and stores a restricted backup without printing environment variables."
confirm "Create the rollback backup now?" || exit 1
BACKUP_DIR="$BACKUP_ROOT/$(date +%Y%m%d-%H%M%S)"
install -d -m 700 "$BACKUP_DIR"
pm2_system save --force
cp /root/.pm2/dump.pm2 "$BACKUP_DIR/dump.before-cutover.pm2"
pm2_system jlist > "$BACKUP_DIR/pm2-jlist.before-cutover.json"
sanitized_pm2_summary "$SYSTEM_PM2_JS" "$SYSTEM_NODE" > "$BACKUP_DIR/pm2-summary.before-cutover.txt"
{
  printf 'system_node='
  "$SYSTEM_NODE" --version
  printf 'git_commit='
  git -C "$PROJECT_ROOT" rev-parse HEAD
  printf 'created_at=%s\n' "$(date --iso-8601=seconds)"
} > "$BACKUP_DIR/versions.before-cutover.txt"
chmod 600 "$BACKUP_DIR"/*
say "Rollback backup created: $BACKUP_DIR"

stage "Install nvm and Node.js 22.23.4"
say "nvm $NVM_VERSION will be installed under $NVM_DIR without editing fish or Bash profiles."
say "The existing /usr/bin/node is deliberately kept for rollback."
confirm "Install nvm and Node.js $TARGET_NODE_VERSION?" || exit 1
curl -fsSL --proto '=https' --tlsv1.2 \
  "https://raw.githubusercontent.com/nvm-sh/nvm/$NVM_VERSION/install.sh" \
  -o "$BACKUP_DIR/nvm-install-$NVM_VERSION.sh"
PROFILE=/dev/null bash "$BACKUP_DIR/nvm-install-$NVM_VERSION.sh"
source_nvm
nvm install "$TARGET_NODE_VERSION"
nvm alias chaineye-production "$TARGET_NODE_VERSION"
nvm use "$TARGET_NODE_VERSION"
TARGET_NODE="$(nvm which "$TARGET_NODE_VERSION")"
TARGET_BIN="$(dirname "$TARGET_NODE")"
npm install --global "pm2@$PM2_VERSION"
TARGET_PM2="$TARGET_BIN/pm2"
[[ "$("$TARGET_NODE" --version)" == "$TARGET_NODE_LABEL" ]]
[[ "$("$TARGET_NODE" -p "require('$TARGET_BIN/../lib/node_modules/pm2/package.json').version")" == "$PM2_VERSION" ]]
say "Installed Node: $TARGET_NODE"
say "Installed PM2: $TARGET_PM2"

stage "Compatibility checks before cutover"
say "These checks use Node $TARGET_NODE_VERSION but do not start or stop any service."
cd "$PROJECT_ROOT"
"$TARGET_NODE" --check src/apiServer.js
"$TARGET_NODE" --check src/crawlerServer.js
"$TARGET_NODE" --check src/botServer.js
"$TARGET_NODE" --check src/singletonJobsServer.js
"$TARGET_NODE" -e '
  const modules = ["axios", "dd-trace", "express", "pg", "redis", "sqlite3"];
  for (const name of modules) {
    require(name);
    console.log("loaded", name);
  }
'
say "Entry-point syntax and critical dependency loading passed under Node $TARGET_NODE_VERSION."
pause "Review the compatibility output, then press Enter to continue."

stage "Switch the PM2 daemon and workers"
warn "This restarts API, crawler, bot, and jobs. A short interruption is expected."
say "Rollback keeps the system Node and the saved PM2 dump intact."
printf '  %sType UPGRADE to continue:%s ' "$YELLOW" "$RESET"
read -r cutover_confirmation
[[ "$cutover_confirmation" == "UPGRADE" ]] || { warn "Cutover cancelled."; exit 1; }
pm2_system save --force
cp /root/.pm2/dump.pm2 "$BACKUP_DIR/dump.immediately-before-cutover.pm2"
chmod 600 "$BACKUP_DIR/dump.immediately-before-cutover.pm2"
CUTOVER_STARTED=1
pm2_system kill
pm2_target resurrect
pm2_target restart \
  luykin-chaineye-api \
  luykin-chaineye-crawler \
  luykin-chaineye-bot \
  luykin-chaineye-jobs \
  --update-env
pm2_target save --force
for _ in $(seq 1 15); do
  if verify_expected_apps_online; then
    break
  fi
  sleep 2
done
if ! verify_expected_apps_online; then
  warn "One or more expected applications are not online."
  if confirm "Roll back to system Node now?"; then
    rollback_to_system_node
  fi
  exit 1
fi
say "All expected PM2 applications report online."

stage "Verify the live runtime"
step "Sanitized PM2 status"
sanitized_pm2_summary "$TARGET_PM2" "$TARGET_NODE"
step "Node binary behind every XHunt worker"
if ! verify_worker_node_versions; then
  warn "At least one worker is not running Node $TARGET_NODE_VERSION."
  if confirm "Roll back to system Node now?"; then
    rollback_to_system_node
  fi
  exit 1
fi
step "API health check"
if ! wait_for_health; then
  warn "API health did not recover within 30 seconds."
  if confirm "Roll back to system Node now?"; then
    rollback_to_system_node
  fi
  exit 1
fi
curl -fsS --max-time 10 "$HEALTH_URL"
printf '\n'
say "Automated runtime and health checks passed."
warn "Before accepting the release, manually inspect recent errors:"
note "  PATH=\"$TARGET_BIN:\$PATH\" $TARGET_PM2 logs luykin-chaineye-api luykin-chaineye-crawler luykin-chaineye-bot luykin-chaineye-jobs --lines 80 --nostream"
pause "Inspect the logs in another terminal, then press Enter to continue."

stage "Optional boot persistence"
say "No PM2 systemd unit was present during the production audit."
say "Enabling one makes the Node $TARGET_NODE_VERSION process list return after a host reboot."
if confirm "Create and enable the pm2-root systemd unit now?"; then
  pm2_target startup systemd -u root --hp /root
  pm2_target save --force
  systemctl status pm2-root --no-pager | sed -n '1,35p'
else
  SKIPPED+=("PM2 systemd boot persistence")
  warn "Skipped. Services stay online, but automatic recovery after a host reboot remains unconfigured."
fi

stage "Record completion and rollback command"
say "Node.js $TARGET_NODE_VERSION is active and the system Node remains installed."
say "Backup directory: $BACKUP_DIR"
say "NVM alias: chaineye-production -> $TARGET_NODE_VERSION"
warn "Keep the backup until the service has been stable through the agreed observation window."
note "To enter the managed runtime manually from fish, run:"
note "  exec bash"
note "  export NVM_DIR=/root/.nvm"
note "  . \"\$NVM_DIR/nvm.sh\""
note "  nvm use chaineye-production"
printf '\n'
warn "Rollback is intentionally not automatic after a successful cutover."
note "Use the rollback section in docs/2026-10/node-22-production-upgrade-runbook.md."

finish
